typedef struct substrait_Expression_Reference_Segment_Struct_Field {
    /* zero-indexed ordinal position of field in struct */
    pb_callback_t field;
    /* Optional child segment */
    pb_callback_t child;
} substrait_Expression_Reference_Segment_Struct_Field_t;

typedef struct substrait_Expression_Reference_Segment_List_Element {
    /* zero-indexed ordinal position of element in list */
    pb_callback_t offset;
    /* Optional child segment */
    pb_callback_t child;
} substrait_Expression_Reference_Segment_List_Element_t;

/* A way to reference the inner property of a complex record. Can reference
 either a map key by literal, a struct field by the ordinal position of
 the desired field or a particular element in an array. Supports
 expressions that would roughly translate to something similar to:
 a.b[2].c['my_map_key'].x where a,b,c and x are struct field references
 (ordinalized in the internal representation here), [2] is a list offset
 and ['my_map_key'] is a reference into a map field. */
typedef struct substrait_Expression_Reference_Segment {
    pb_size_t which_reference_type;
    union substrait_Expression_Reference_Segment_reference_type {
        substrait_Expression_Reference_Segment_Map_Key_t map_key;
        substrait_Expression_Reference_Segment_Struct_Field_t struct_field;
        substrait_Expression_Reference_Segment_List_Element_t list_element;
    } reference_type;
} substrait_Expression_Reference_Segment_t;

typedef struct substrait_Expression_Mask_Expression_Struct_Select {
    pb_callback_t struct_items;
} substrait_Expression_Mask_Expression_Struct_Select_t;

/* A reference that takes an existing subtype and selectively removes fields
 from it. For example, one might initially have an inner struct with 100
 fields but a a particular operation only needs to interact with only 2 of
 those 100 fields. In this situation, one would use a mask expression to
 eliminate the 98 fields that are not relevant to the rest of the operation
 pipeline.

 Note that this does not fundamentally alter the structure of data beyond
 the elimination of unnecessary elements. */
typedef struct substrait_Expression_Mask_Expression {
    bool has_select;
    substrait_Expression_Mask_Expression_Struct_Select_t select;
    bool maintain_singular_struct;
} substrait_Expression_Mask_Expression_t;

typedef struct substrait_Expression_Mask_Expression_List_Select {
    pb_callback_t selection;
    pb_callback_t child;
} substrait_Expression_Mask_Expression_List_Select_t;

typedef struct substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Element {
    int32_t field;
} substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Element_t;

typedef struct substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Slice {
    int32_t start;
    int32_t end;
} substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Slice_t;

typedef struct substrait_Expression_Mask_Expression_List_Select_List_Select_Item {
    pb_size_t which_type;
    union substrait_Expression_Mask_Expression_List_Select_List_Select_Item_type {
        substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Element_t item;
        substrait_Expression_Mask_Expression_List_Select_List_Select_Item_List_Slice_t slice;
    } type;
} substrait_Expression_Mask_Expression_List_Select_List_Select_Item_t;

typedef struct substrait_Expression_Mask_Expression_Map_Select {
    pb_size_t which_select;
    union substrait_Expression_Mask_Expression_Map_Select_select {
        pb_callback_t key;
        pb_callback_t expression;
    } select;
    pb_callback_t child;
} substrait_Expression_Mask_Expression_Map_Select_t;

typedef struct substrait_Expression_Mask_Expression_Select {
    pb_size_t which_type;
    union substrait_Expression_Mask_Expression_Select_type {
        substrait_Expression_Mask_Expression_Struct_Select_t struct_;
        substrait_Expression_Mask_Expression_List_Select_t list;
        substrait_Expression_Mask_Expression_Map_Select_t map;
    } type;
} substrait_Expression_Mask_Expression_Select_t;

typedef struct substrait_Expression_Mask_Expression_Struct_Item {
    int32_t field;
    bool has_child;
    substrait_Expression_Mask_Expression_Select_t child;
} substrait_Expression_Mask_Expression_Struct_Item_t;

typedef struct substrait_Expression_Mask_Expression_Map_Select_Map_Key {
    pb_callback_t map_key;
} substrait_Expression_Mask_Expression_Map_Select_Map_Key_t;

typedef struct substrait_Expression_Mask_Expression_Map_Select_Map_Key_Expression {
    pb_callback_t map_key_expression;
} substrait_Expression_Mask_Expression_Map_Select_Map_Key_Expression_t;

/* A reference to an inner part of a complex object. Can reference reference a
 single element or a masked version of elements */
typedef struct substrait_Expression_Field_Reference {
    pb_size_t which_reference_type;
    union substrait_Expression_Field_Reference_reference_type {
        pb_callback_t direct_reference;
        pb_callback_t masked_reference;
    } reference_type;
    pb_size_t which_root_type;
    union substrait_Expression_Field_Reference_root_type {
        pb_callback_t expression;
        pb_callback_t root_reference;
        pb_callback_t outer_reference;
    } root_type;
} substrait_Expression_Field_Reference_t;

/* Hash joins and merge joins are a specialization of the general join where the join
 expression is an series of comparisons between fields that are ANDed together.  The
 behavior of this comparison is flexible */
typedef struct substrait_Comparison_Join_Key {
    /* The key to compare from the left table */
    bool has_left;
    substrait_Expression_Field_Reference_t left;
    /* The key to compare from the right table */
    bool has_right;
    substrait_Expression_Field_Reference_t right;
    /* Describes how to compare the two keys */
    bool has_comparison;
    substrait_Comparison_Join_Key_Comparison_Type_t comparison;
} substrait_Comparison_Join_Key_t;

/* Singleton that expresses this FieldReference is rooted off the root
 incoming record type */
typedef struct substrait_Expression_Field_Reference_Root_Reference {
    char dummy_field;
} substrait_Expression_Field_Reference_Root_Reference_t;

/* A root reference for the outer relation's subquery */
typedef struct substrait_Expression_Field_Reference_Outer_Reference {
    /* number of subquery boundaries to traverse up for this field's reference

 This value must be >= 1 */
    uint32_t steps_out;
} substrait_Expression_Field_Reference_Outer_Reference_t;

/* A subquery with one row and one column. This is often an aggregate
 though not required to be. */
typedef struct substrait_Expression_Subquery_Scalar {
    bool has_input;
    substrait_Rel_t input;
} substrait_Expression_Subquery_Scalar_t;

/* Predicate checking that the left expression is contained in the right
 subquery

 Examples:

 x IN (SELECT * FROM t)
 (x, y) IN (SELECT a, b FROM t) */
typedef struct substrait_Expression_Subquery_In_Predicate {
    pb_callback_t needles;
    bool has_haystack;
    substrait_Rel_t haystack;
} substrait_Expression_Subquery_In_Predicate_t;

/* A predicate over a set of rows in the form of a subquery
 EXISTS and UNIQUE are common SQL forms of this operation. */
typedef struct substrait_Expression_Subquery_Set_Predicate {
    /* TODO: should allow expressions */
    substrait_Expression_Subquery_Set_Predicate_Predicate_Op_t predicate_op;
    bool has_tuples;
    substrait_Rel_t tuples;
} substrait_Expression_Subquery_Set_Predicate_t;

/* A subquery comparison using ANY or ALL.
 Examples:

 SELECT *
 FROM t1
 WHERE x < ANY(SELECT y from t2) */
typedef struct substrait_Expression_Subquery_Set_Comparison {
    /* ANY or ALL */
    pb_callback_t reduction_op;
    /* A comparison operator */
    pb_callback_t comparison_op;
    /* left side of the expression */
    pb_callback_t left;
    /* right side of the expression */
    pb_callback_t right;
} substrait_Expression_Subquery_Set_Comparison_t;

/* Subquery relation expression */
typedef struct substrait_Expression_Subquery {
    pb_size_t which_subquery_type;
    union substrait_Expression_Subquery_subquery_type {
        /* Scalar subquery */
        substrait_Expression_Subquery_Scalar_t scalar;
        /* x IN y predicate */
        substrait_Expression_Subquery_In_Predicate_t in_predicate;
        /* EXISTS/UNIQUE predicate */
        substrait_Expression_Subquery_Set_Predicate_t set_predicate;
        /* ANY/ALL predicate */
        substrait_Expression_Subquery_Set_Comparison_t set_comparison;
    } subquery_type;
} substrait_Expression_Subquery_t;

/* Expression that represents a dynamic parameter.
 Dynamic parameters are identified by a surrogate key within a plan. */
typedef struct substrait_Dynamic_Parameter {
    /* The type of the dynamic parameter. */
    bool has_type;
    substrait_Type_t type;
    /* The surrogate key used within a plan to reference a specific parameter binding. */
    uint32_t parameter_reference;
} substrait_Dynamic_Parameter_t;

typedef struct substrait_Expression {
    pb_size_t which_rex_type;
    union substrait_Expression_rex_type {
        substrait_Expression_Literal_t literal;
        substrait_Expression_Field_Reference_t selection;
        substrait_Expression_Scalar_Function_t scalar_function;
        substrait_Expression_Window_Function_t window_function;
        substrait_Expression_If_Then_t if_then;
        substrait_Expression_Switch_Expression_t switch_expression;
        substrait_Expression_Singular_Or_List_t singular_or_list;
        substrait_Expression_Multi_Or_List_t multi_or_list;
        /* deprecated: enum literals are only sensible in the context of
     function arguments, for which FunctionArgument should now be
     used */
        substrait_Expression_Enum_t enum_;
        substrait_Expression_Cast_t cast;
        substrait_Expression_Subquery_t subquery;
        substrait_Expression_Nested_t nested;
        substrait_Dynamic_Parameter_t dynamic_parameter;
    } rex_type;
} substrait_Expression_t;

/* The scan operator of base data (physical or virtual), including filtering and projection. */
typedef struct substrait_Read_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_base_schema;
    substrait_Named_Struct_t base_schema;
    bool has_filter;
    substrait_Expression_t filter;
    bool has_projection;
    substrait_Expression_Mask_Expression_t projection;
    pb_size_t which_read_type;
    union substrait_Read_Rel_read_type {
        substrait_Read_Rel_Virtual_Table_t virtual_table;
        substrait_Read_Rel_Local_Files_t local_files;
        substrait_Read_Rel_Named_Table_t named_table;
        substrait_Read_Rel_Extension_Table_t extension_table;
        substrait_Read_Rel_Iceberg_Table_t iceberg_table;
    } read_type;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
    bool has_best_effort_filter;
    substrait_Expression_t best_effort_filter;
} substrait_Read_Rel_t;

/* The binary JOIN relational operator left-join-right, including various join types, a join condition and post_join_filter expression */
typedef struct substrait_Join_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_left;
    substrait_Rel_t left;
    bool has_right;
    substrait_Rel_t right;
    bool has_expression;
    substrait_Expression_t expression;
    bool has_post_join_filter;
    substrait_Expression_t post_join_filter;
    substrait_Join_Rel_Join_Type_t type;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Join_Rel_t;

/* The relational operator representing LIMIT/OFFSET or TOP type semantics. */
typedef struct substrait_Fetch_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_input;
    substrait_Rel_t input;
    pb_size_t which_offset_mode;
    union substrait_Fetch_Rel_offset_mode {
        /* the offset expressed in number of records
     Deprecated: use `offset_expr` instead */
        int64_t offset;
        /* Expression evaluated into a non-negative integer specifying the number
     of records to skip. An expression evaluating to null is treated as 0.
     Evaluating to a negative integer should result in an error.
     Recommended type for offset is int64. */
        substrait_Expression_t offset_expr;
    } offset_mode;
    pb_size_t which_count_mode;
    union substrait_Fetch_Rel_count_mode {
        /* the amount of records to return
     use -1 to signal that ALL records should be returned
     Deprecated: use `count_expr` instead */
        int64_t count;
        /* Expression evaluated into a non-negative integer specifying the number
     of records to return. An expression evaluating to null signals that ALL
     records should be returned.
     Evaluating to a negative integer should result in an error.
     Recommended type for count is int64. */
        substrait_Expression_t count_expr;
    } count_mode;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Fetch_Rel_t;

/* The relational operator capturing simple FILTERs (as in the WHERE clause of SQL) */
typedef struct substrait_Filter_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_input;
    substrait_Rel_t input;
    bool has_condition;
    substrait_Expression_t condition;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Filter_Rel_t;

/* Returns a single bucket number per record. */
typedef struct substrait_Exchange_Rel_Single_Bucket_Expression {
    bool has_expression;
    substrait_Expression_t expression;
} substrait_Exchange_Rel_Single_Bucket_Expression_t;

/* Returns zero or more bucket numbers per record */
typedef struct substrait_Exchange_Rel_Multi_Bucket_Expression {
    bool has_expression;
    substrait_Expression_t expression;
    bool constrained_to_count;
} substrait_Exchange_Rel_Multi_Bucket_Expression_t;

/* A redistribution operation */
typedef struct substrait_Exchange_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_input;
    substrait_Rel_t input;
    int32_t partition_count;
    pb_callback_t targets;
    pb_size_t which_exchange_kind;
    union substrait_Exchange_Rel_exchange_kind {
        substrait_Exchange_Rel_Scatter_Fields_t scatter_by_fields;
        substrait_Exchange_Rel_Single_Bucket_Expression_t single_target;
        substrait_Exchange_Rel_Multi_Bucket_Expression_t multi_target;
        substrait_Exchange_Rel_Round_Robin_t round_robin;
        substrait_Exchange_Rel_Broadcast_t broadcast;
    } exchange_kind;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Exchange_Rel_t;

typedef struct substrait_Expand_Rel_Expand_Field {
    pb_size_t which_field_type;
    union substrait_Expand_Rel_Expand_Field_field_type {
        /* Field that switches output based on which duplicate is being output.  Every
     switching_field should contain the same number of duplicates (so that the output rows
     are of consistent size and type).  If there are not enough switching field definitions
     to match the other field definitions NULL will be returned to fill the extras. */
        substrait_Expand_Rel_Switching_Field_t switching_field;
        /* Field that outputs the same value no matter which duplicate is being output.  Equivalent
     to a switching_field that lists the same expression multiple times. */
        substrait_Expression_t consistent_field;
    } field_type;
} substrait_Expand_Rel_Expand_Field_t;

/* The operator that modifies the columns of a table */
typedef struct substrait_Update_Rel {
    pb_size_t which_update_type;
    union substrait_Update_Rel_update_type {
        substrait_Named_Table_t named_table;
    } update_type;
    bool has_table_schema;
    substrait_Named_Struct_t table_schema; /* The full schema of the named_table */
    bool has_condition;
    substrait_Expression_t condition; /* condition to be met for the update to be applied on a record */
    /* The list of transformations to apply to the columns of the named_table */
    pb_callback_t transformations;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Update_Rel_t;

typedef struct substrait_Update_Rel_Transform_Expression {
    bool has_transformation;
    substrait_Expression_t transformation; /* the transformation to apply */
    int32_t column_target; /* index of the column to apply the transformation to */
} substrait_Update_Rel_Transform_Expression_t;

/* The hash equijoin join operator will build a hash table out of the right input based on a set of join keys.
 It will then probe that hash table for incoming inputs, finding matches.

 Two rows are a match if the comparison function returns true for all keys */
typedef struct substrait_Hash_Join_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_left;
    substrait_Rel_t left;
    bool has_right;
    substrait_Rel_t right;
    /* These fields are deprecated in favor of `keys`.  If they are set then
 the two lists (left_keys and right_keys) must have the same length and
 the comparion function is considered to be SimpleEqualityType::EQ */
    pb_callback_t left_keys;
    pb_callback_t right_keys;
    bool has_post_join_filter;
    substrait_Expression_t post_join_filter;
    substrait_Hash_Join_Rel_Join_Type_t type;
    /* One or more keys to join on.  The relation is invalid if this is empty
 (unless the deprecated left_keys/right_keys fields are being used).

 If a custom comparison function is used then it must be consistent with
 the hash function used for the keys.

 In other words, the hash function must return the same hash code when the
 comparison returns true.  For example, if the comparison function is
 "equals ignoring case" then the hash function must return the same hash
 code for strings that differ only by case.  Note: the hash function is not
 specified here.  It is the responsibility of the consumer to find an appropriate
 hash function for a given comparsion function or to reject the plan if it cannot
 do so. */
    pb_callback_t keys;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Hash_Join_Rel_t;

/* The merge equijoin does a join by taking advantage of two sets that are sorted on the join keys.
 This allows the join operation to be done in a streaming fashion. */
typedef struct substrait_Merge_Join_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_left;
    substrait_Rel_t left;
    bool has_right;
    substrait_Rel_t right;
    /* These fields are deprecated in favor of `keys`.  If they are set then
 the two lists (left_keys and right_keys) must have the same length and
 the comparion function is considered to be SimpleEqualityType::EQ */
    pb_callback_t left_keys;
    pb_callback_t right_keys;
    bool has_post_join_filter;
    substrait_Expression_t post_join_filter;
    substrait_Merge_Join_Rel_Join_Type_t type;
    /* One or more keys to join on.  The relation is invalid if this is empty
 (unless the deprecated left_keys/right_keys fields are being used).

 If a custom comparison function is used then it must be consistent with
 the ordering of the input data.  For example, if the comparison function
 is "<" then we generally expect the data to be sorted in ascending order.

 If the comparison function is something like "less than ignoring case" then
 the data should be sorted appropriately (e.g. both "A" and "a" should come
 before "b")

 The sort order is not specified here.  It is typically the responsibility of
 the producer to ensure the plan sorts the data if needed (although the consumer
 is free to do so as well).  If possible, the consumer should verify the sort
 order and reject invalid plans. */
    pb_callback_t keys;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Merge_Join_Rel_t;

/* The nested loop join (NLJ) operator will hold the entire right input and iterate over it using the
 left input, evaluating the join expression on the Cartesian product of all rows. */
typedef struct substrait_Nested_Loop_Join_Rel {
    bool has_common;
    substrait_Rel_Common_t common;
    bool has_left;
    substrait_Rel_t left;
    bool has_right;
    substrait_Rel_t right;
    /* optional, defaults to true (a cartesian join) */
    bool has_expression;
    substrait_Expression_t expression;
    substrait_Nested_Loop_Join_Rel_Join_Type_t type;
    bool has_advanced_extension;
    substrait_extensions_Advanced_Extension_t advanced_extension;
} substrait_Nested_Loop_Join_Rel_t;

/* The argument of a function */
typedef struct substrait_Function_Argument {
    pb_size_t which_arg_type;
    union substrait_Function_Argument_arg_type {
        pb_callback_t enum_;
        substrait_Type_t type;
        substrait_Expression_t value;
    } arg_type;
} substrait_Function_Argument_t;

typedef struct substrait_Expression_Nested_Map_Key_Value {
    /* Mandatory key/value expressions. */
    bool has_key;
    substrait_Expression_t key;
    bool has_value;
    substrait_Expression_t value;
} substrait_Expression_Nested_Map_Key_Value_t;

typedef struct substrait_Expression_If_Then_If_Clause {
    bool has_if_;
    substrait_Expression_t if_;
    bool has_then;
    substrait_Expression_t then;
} substrait_Expression_If_Then_If_Clause_t;

typedef struct substrait_Expression_Switch_Expression_If_Value {
    bool has_if_;
    substrait_Expression_Literal_t if_;
    bool has_then;
    substrait_Expression_t then;
} substrait_Expression_Switch_Expression_If_Value_t;

/* The description of a field to sort on (including the direction of sorting and null semantics) */
typedef struct substrait_Sort_Field {
    bool has_expr;
    substrait_Expression_t expr;
    pb_size_t which_sort_kind;
    union substrait_Sort_Field_sort_kind {
        substrait_Sort_Field_Sort_Direction_t direction;
        uint32_t comparison_function_reference;
    } sort_kind;
} substrait_Sort_Field_t;

/* An aggregate function. */
typedef struct substrait_Aggregate_Function {
    /* Points to a function_anchor defined in this plan, which must refer
 to an aggregate function in the associated YAML file. Required; 0 is
 considered to be a valid anchor/reference. */
    uint32_t function_reference;
    /* deprecated; use arguments instead */
    pb_callback_t args;
    /* If specified, the aggregated records are ordered according to this list
 before they are aggregated. The first sort field has the highest
 priority; only if a sort field determines two records to be equivalent is
 the next field queried. This field is optional. */
    pb_callback_t sorts;
    /* Describes which part of the aggregation to perform within the context of
 distributed algorithms. Required. Must be set to INITIAL_TO_RESULT for
 aggregate functions that are not decomposable. */
    substrait_Aggregation_Phase_t phase;
    /* Must be set to the return type of the function, exactly as derived
 using the declaration in the extension. */
    bool has_output_type;
    substrait_Type_t output_type;
    /* Specifies whether equivalent records are merged before being aggregated.
 Optional, defaults to AGGREGATION_INVOCATION_ALL. */
    substrait_Aggregate_Function_Aggregation_Invocation_t invocation;
    /* The arguments to be bound to the function. This must have exactly the
 number of arguments specified in the function definition, and the
 argument types must also match exactly:

  - Value arguments must be bound using FunctionArgument.value, and
    the expression in that must yield a value of a type that a function
    overload is defined for.
  - Type arguments must be bound using FunctionArgument.type, and a
    function overload must be defined for that type.
  - Enum arguments must be bound using FunctionArgument.enum
    followed by Enum.specified, with a string that case-insensitively
    matches one of the allowed options.
  - Optional enum arguments must be bound using FunctionArgument.enum
    followed by either Enum.specified or Enum.unspecified. If specified,
    the string must case-insensitively match one of the allowed options. */
    pb_callback_t arguments;
    /* Options to specify behavior for corner cases, or leave behavior
 unspecified if the consumer does not need specific behavior in these
 cases. */
    pb_callback_t options;
} substrait_Aggregate_Function_t;

typedef struct substrait_Aggregate_Rel_Measure {
    bool has_measure;
    substrait_Aggregate_Function_t measure;
    /* An optional boolean expression that acts to filter which records are
 included in the measure. True means include this record for calculation
 within the measure.
 Helps to support SUM(<c>) FILTER(WHERE...) syntax without masking opportunities for optimization */
    bool has_filter;
    substrait_Expression_t filter;
} substrait_Aggregate_Rel_Measure_t;

/* This rel is used  to create references,
 in case we refer to a RelRoot field names will be ignored */
typedef struct substrait_Reference_Rel {
    int32_t subtree_ordinal;
} substrait_Reference_Rel_t;


